<script setup lang="ts">
import { computed, ref } from 'vue'
import { onLoad, onNavigationBarButtonTap, onUnload } from '@dcloudio/uni-app'
import { sessionStore } from '@/store/session'
type Key='core'|'quality'|'distribution'|'arrival'|'centralProcurement'|'packing'|'logistics'|'supplier'|'agri'
const defaults:Key[]=['core','quality','distribution','arrival','centralProcurement','packing','logistics','supplier','agri']
const labels:Record<Key,string>={core:'核心',quality:'质检',distribution:'配货',arrival:'到场货',centralProcurement:'集采',packing:'打包',logistics:'物流',supplier:'供应商',agri:'农资'}
const capability:Record<Key,string[]>={core:[],quality:['quality.view'],distribution:['distribution.view'],arrival:['admission.view'],centralProcurement:[],packing:['packing.view'],logistics:['logistics.view'],supplier:['baseManagement.view'],agri:['agriMaterial.view']}
const order=ref<Key[]>([]),saved=ref<Key[]>([]),committed=ref(false),dragging=ref(-1)
const key=computed(()=>`dataCenterCategoryOrder:${sessionStore.state.userId}`)
function initial(){const allowed=defaults.filter(x=>!capability[x].length||sessionStore.canAny(capability[x]));const local=uni.getStorageSync(key.value) as Key[];const valid=Array.isArray(local)?local.filter(x=>allowed.includes(x)):[];const merged=[...valid,...allowed.filter(x=>!valid.includes(x))];if(allowed.includes('arrival')&&!valid.includes('arrival')){const current=merged.indexOf('arrival');if(current>=0)merged.splice(current,1);const distributionIndex=merged.indexOf('distribution');merged.splice(distributionIndex>=0?distributionIndex+1:0,0,'arrival')}order.value=merged;saved.value=[...order.value]}
function move(from:number,to:number){if(to<0||to>=order.value.length||from===to)return;const list=[...order.value];const [item]=list.splice(from,1);list.splice(to,0,item);order.value=list}
function start(i:number){dragging.value=i;uni.vibrateShort({})}
function drop(i:number){if(dragging.value>=0)move(dragging.value,i);dragging.value=-1}
function reset(){order.value=defaults.filter(x=>order.value.includes(x))}
function save(){uni.setStorageSync(key.value,[...order.value]);saved.value=[...order.value];committed.value=true;uni.showToast({title:'顺序已保存',icon:'success'});setTimeout(()=>uni.navigateBack(),350)}
function dirty(){return JSON.stringify(order.value)!==JSON.stringify(saved.value)}
function askLeave(){if(!dirty())return uni.navigateBack();uni.showModal({title:'放弃修改？',content:'当前分类顺序尚未保存。',confirmText:'放弃',success:r=>{if(r.confirm){committed.value=true;uni.navigateBack()}}})}
onLoad(initial);onNavigationBarButtonTap(askLeave);onUnload(()=>{if(!committed.value&&dirty())uni.setStorageSync('dataCenterSortDraft',order.value)})
</script>
<template><view class="page"><view class="tip">拖动调整分类顺序，前4个显示在顶部，其余显示在“更多”中。</view><view class="list"><template v-for="(item,i) in order" :key="item"><view v-if="i===4" class="divider"><span/>以下分类显示在更多中<span/></view><view :class="['row',{dragging:dragging===i}]" @longpress="start(i)" @touchend="drop(i)"><text class="handle">☰</text><b>{{labels[item]}}</b><view class="moves"><text :class="{disabled:i===0}" @click.stop="move(i,i-1)">上移</text><text :class="{disabled:i===order.length-1}" @click.stop="move(i,i+1)">下移</text></view></view></template></view><view class="actions"><button @click="reset">恢复默认</button><button class="primary" @click="save">保存</button></view></view></template>
<style scoped>.page{min-height:100vh;padding:24rpx 24rpx 150rpx;background:var(--wms-surface-page)}.tip{padding:20rpx;border:1rpx solid var(--wms-border);border-radius:10rpx;background:#fff;color:var(--wms-text-secondary);font-size:23rpx;line-height:1.55}.list{margin-top:16rpx}.row{display:flex;height:88rpx;align-items:center;margin-bottom:10rpx;padding:0 20rpx;border:1rpx solid var(--wms-border);border-radius:10rpx;background:#fff}.row.dragging{border-color:var(--wms-primary-700);box-shadow:var(--wms-shadow-card)}.handle{margin-right:20rpx;color:var(--wms-text-secondary);font-size:30rpx}.row b{font-size:27rpx}.moves{display:flex;gap:22rpx;margin-left:auto}.moves text{color:var(--wms-primary-700);font-size:22rpx}.moves .disabled{color:var(--wms-text-secondary);opacity:.45}.divider{display:flex;align-items:center;gap:12rpx;margin:18rpx 0;color:var(--wms-text-secondary);font-size:21rpx}.divider span{height:1rpx;flex:1;background:var(--wms-border)}.actions{position:fixed;right:0;bottom:0;left:0;display:grid;grid-template-columns:1fr 1fr;gap:14rpx;padding:16rpx 24rpx calc(16rpx + env(safe-area-inset-bottom));border-top:1rpx solid var(--wms-border);background:#fff}.actions button{font-size:26rpx}.actions .primary{background:var(--wms-primary-700);color:#fff}</style>
